(function () {
  app.modals.LookupModal = function () {
    var _modalManager;
    var _dataTable;
    var _$table;
    var _$filterInput;

    var _options = {
      serviceMethod: null, //Required
      title: app.localize('SelectAnItem'),
      loadOnStartup: true,
      showFilter: true,
      filterText: '',
      excludeCurrentUser: false,
      pageSize: app.consts.grid.defaultPageSize,
      canSelect: function (item) {
        /* This method can return boolean or a promise which returns boolean.
         * A false value is used to prevent selection.
         */
        return true;
      },
    };

    function refreshTable() {
      _dataTable.ajax.reload();
    }

    function selectItem(item) {
      var boolOrPromise = _options.canSelect(item);
      if (!boolOrPromise) {
        return;
      }

      if (boolOrPromise === true) {
        _modalManager.setResult(item);
        _modalManager.close();
        return;
      }

      //assume as promise
      boolOrPromise.then(function (result) {
        if (result) {
          _modalManager.setResult(item);
          _modalManager.close();
        }
      });
    }

    this.init = function (modalManager) {
      _modalManager = modalManager;
      _options = $.extend(_options, _modalManager.getOptions().lookupOptions);
      _$table = _modalManager.getModal().find('.lookup-modal-table');

      _dataTable = _$table.DataTable({
        paging: true,
        serverSide: true,
        processing: true,
        lengthChange: false,
        pageLength: _options.pageSize,
        deferLoading: _options.loadOnStartup ? null : 0,
        listAction: {
          ajaxFunction: _options.serviceMethod,
          inputFilter: function () {
            return $.extend(
              {
                filter: _$filterInput.val(),
                excludeCurrentUser: _options.excludeCurrentUser,
              },
              _modalManager.getArgs().extraFilters
            );
          },
        },
        columnDefs: [
          {
            targets: 0,
            data: null,
            orderable: false,
            defaultContent: '',
            className: 'text-center',
            rowAction: {
              element: $('<button/>')
                    .addClass('btn btn-icon btn-bg-light btn-active-color-primary btn-sm')
                .attr('title', app.localize('Select'))
                .append($('<i/>').addClass('la la-chevron-circle-right'))
                .click(function () {
                  var record = $(this).data();
                  selectItem(record);
                }),
            },
          },
          {
            targets: 1,
            data: 'name',
          },
        ],
      });

      _modalManager
        .getModal()
        .find('.lookup-filter-button')
        .click(function (e) {
          e.preventDefault();
          refreshTable();
        });

      _modalManager
        .getModal()
        .find('.modal-body')
        .keydown(function (e) {
          if (e.which === 13) {
            e.preventDefault();
            refreshTable();
          }
        });

      _$filterInput = _modalManager.getModal().find('.lookup-filter-text');
      _$filterInput.val(_options.filterText);
    };
  };

  app.modals.LookupModal.create = function (lookupOptions) {
    return new app.ModalManager({
      viewUrl: abp.appPath + 'App/Common/LookupModal',
      scriptUrl: abp.appPath + 'view-resources/App/Common/Modals/_LookupModal.js',
      modalClass: 'LookupModal',
      lookupOptions: lookupOptions,
    });
  };
})();

(function () {
	app.modals.SortingModal = function () {
		var _modalManager;
		var _dataTable;
		var _$table;
		var _$sortinglist;
		var _$filterInput;
		var _$onUpdating = false;

		var _options = {
			serviceMethod: null,
			title: app.localize('SelectAnItem'),
			loadOnStartup: true,
			showFilter: true,
			filterText: '',
			excludeCurrentUser: false,
			pageSize: app.consts.grid.defaultPageSize,
			onSelectionDone: function () { },
			canSelect: function (item) {
				/* This method can return boolean or a promise which returns boolean.
				 * A false value is used to prevent selection.
				 */
				return true;
			},
		};

		this.init = function (modalManager) {
			_modalManager = modalManager;
			_options = $.extend(_options, _modalManager.getOptions().lookupOptions);

			_$filterInput = _modalManager.getArgs().extraFilters;
			if (_$filterInput == null) {
				_options.serviceMethod().done(function (results) {
					DrawSortableList(results);
				});
			}
			else {
				_options.serviceMethod(_modalManager.getArgs().extraFilters).done(function (results) {
					DrawSortableList(results);
				});
			}

			function DrawSortableList(results) {
				$.each(results.items, function (index, data) {
					$('#sortableList').append(
						$('<li data-id="' + data.value + '">').addClass('inbox-data list-group-item d-flex align-items-center').append(
							$("<div>").addClass('moveHandler').append($('<i class="fa fa-arrows-alt moveWidget"></i> '))
						).append(
							$("<div>").addClass('sorting-item').append(
								$("<div>").addClass('ms-1').append(
									$("<span>").html(data.name)
								)
							)
						)
					);
				});
			}

			var sortingListEle = document.getElementById('sortableList');
			_$sortinglist = new Sortable(sortingListEle, {
				animation: 150,
				handle: '.moveHandler',
			});

			_modalManager.onBeforeClose(function () {
				if (typeof _options.onSelectionDone == 'function' && _$onUpdating) {
					var itemIds = [];

					$('#sortableList').find('li').each(function () {
						itemIds.push($(this)[0].dataset.id);
					});

					_options.onSelectionDone(_modalManager.getArgs().extraFilters, itemIds);
				}
			});

			$('.save-button').click(function (e) {
				_$onUpdating = true;
			});

			$('.close-button').click(function (e) {
				_$onUpdating = false;
			});

		};
	};

	app.modals.SortingModal.create = function (lookupOptions) {
		return new app.ModalManager({
			viewUrl: abp.appPath + 'App/Common/SortingModal',
			scriptUrl: abp.appPath + 'view-resources/App/Common/Modals/_SortingModal.js',
			modalClass: 'SortingModal',
			lookupOptions: lookupOptions,
		});
	};
})();

(function ($) {
	app.modals.CropImageModal = function () {
		var _modalManager;
		var $cropperJsApi = null;

		var _options = {
			serviceMethod: null,
			title: app.localize('UpdateImageAspectRatio'),
			imgData: null,
			//loadOnStartup: true,
			//onSelectionDone: function () { }
		};

		this.init = function (modalManager) {
			_modalManager = modalManager;
			_options = $.extend(_options, _modalManager.getOptions().cropImageOptions);
			//console.log(_options);

			$aspectHeight = _modalManager.getModal().find('#RatioHeight');
			$aspectWidth = _modalManager.getModal().find('#RatioWidth');
			$aspectWidth = _modalManager.getModal().find('#RatioWidth');

			var $profilePictureResize = $('#CommonImageResize');
			if (_options.imgData)
				$profilePictureResize.attr('src', _options.imgData);

			_modalManager.setBusy(true);
			setTimeout(function () {

				//console.log($aspectWidth, $aspectHeight);
				$cropperJsApi = $profilePictureResize.cropper({
					aspectRatio: $aspectWidth.val() / $aspectHeight.val(),
					viewMode: 1,
					autoCropArea: 1
				});
				_modalManager.setBusy(false);
			}, 500);



		};

		this.save = function () {
			//$('.preview-primaryimg').attr('src', $cropperJsApi.cropper('getCroppedCanvas').toDataURL("image/png"));
			//_modalManager.setResult($cropperJsApi.cropper('getCroppedCanvas').toDataURL("image/png"));
			//_modalManager.setResult($cropperJsApi.cropper('getCroppedCanvas').toBlob());
			//_modalManager.close();

			$cropperJsApi.cropper('getCroppedCanvas').toBlob(function (blob) {
				_modalManager.setResult(blob);

				// clear 
				if ($cropperJsApi) {
					$cropperJsApi = null;
				}

				_modalManager.close();

			});


		};
	};

	app.modals.CropImageModal.create = function (cropImageOptions) {
		return new app.ModalManager({
			viewUrl: abp.appPath + 'App/Common/CropImageModal',
			scriptUrl: abp.appPath + 'view-resources/App/Common/Modals/_CropImageModal.js',
			modalClass: 'CropImageModal',
			cropImageOptions: cropImageOptions,
		});
	};

})(jQuery);

(function () {
  app.modals.EntityTypeHistoryModal = function () {
    var _modalManager;
    var _dataTable;
    var _$table;
    var _args;

    var _auditLogService = abp.services.app.auditLog;

    var _options = {
      serviceMethod: null, //Required
      title: app.localize('SelectAnItem'),
      loadOnStartup: true,
      showFilter: true,
      filterText: '',
      pageSize: app.consts.grid.defaultPageSize,
      canSelect: function (item) {
        /* This method can return boolean or a promise which returns boolean.
         * A false value is used to prevent selection.
         */
        return true;
      },
    };

    function refreshTable() {
      _dataTable.ajax.reload();
    }

    function showEntityChangeDetails(entityChange) {
      var entityChangeDetailModal = new app.ModalManager({
        viewUrl: abp.appPath + 'App/AuditLogs/EntityChangeDetailModal',
        modalClass: 'EntityChangeDetailModal',
      });

      entityChangeDetailModal.open({ entityChangeListDto: entityChange });
    }

    this.init = function (modalManager) {
      _modalManager = modalManager;

      _options = $.extend(_options, _modalManager.getOptions().lookupOptions);
      _$table = _modalManager.getModal().find('.entity-type-history-table');
      _args = _modalManager.getArgs();

      _dataTable = _$table.DataTable({
        paging: true,
        serverSide: true,
        processing: true,
        lengthChange: false,
        pageLength: _options.pageSize,
        deferLoading: _options.loadOnStartup ? null : 0,
        listAction: {
          ajaxFunction: _auditLogService.getEntityTypeChanges,
          inputFilter: function () {
            return {
              entityTypeFullName: _args.entityTypeFullName,
              entityId: _args.entityId,
            };
          },
        },
        columnDefs: [
          {
            targets: 0,
            data: null,
            orderable: false,
            defaultContent: '',
            rowAction: {
              element: $('<div/>')
                .addClass('text-center')
                .append(
                  $('<button/>')
                    .addClass('btn btn-outline-primary btn-sm btn-icon')
                    .attr('title', app.localize('EntityChangeDetail'))
                    .append($('<i/>').addClass('fa fa-search'))
                )
                .click(function () {
                  showEntityChangeDetails($(this).data());
                }),
            },
          },
          {
            targets: 1,
            data: 'changeTypeName',
            orderable: false,
            render: function (changeTypeName) {
              return app.localize(changeTypeName);
            },
          },
          {
            targets: 2,
            data: 'userName',
          },
          {
            targets: 3,
            data: 'changeTime',
            render: function (changeTime) {
              return moment(changeTime).format('L LT');
            },
          },
        ],
      });

      refreshTable();
    };
  };

  app.modals.EntityTypeHistoryModal.create = function () {
    return new app.ModalManager({
      viewUrl: abp.appPath + 'App/Common/EntityTypeHistoryModal',
      scriptUrl: abp.appPath + 'view-resources/App/Common/Modals/_EntityTypeHistoryModal.js',
      modalClass: 'EntityTypeHistoryModal',
    });
  };
})();
